static z_t53_t z_t58_replaceFirst(
    const z_t58_t* self, const z_t58_t* needle,
    const z_t58_t* replacement) {
    return z_t58_replace_impl(self, needle, replacement, true);
}

static z_t53_t z_t58_repeated(const z_t58_t* self, uint64_t n);
static z_t53_t z_t58_repeated(const z_t58_t* self, uint64_t n) {
    z_t53_t z = {0};
    uint64_t total = self->size * n;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    for (uint64_t i = 0; i < n; i++) {
        memcpy(z.data + i * self->size, self->data, self->size);
    }
    z.data[total] = '\0';
    return z;
}

static z_t53_t z_t58_concat(
    const z_t58_t* self, const z_t58_t* other);
static z_t53_t z_t58_concat(
    const z_t58_t* self, const z_t58_t* other) {
    z_t53_t z = {0};
    uint64_t total = self->size + other->size;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->size);
    memcpy(z.data + self->size, other->data, other->size);
    z.data[total] = '\0';
    return z;
}

static z_t53_t z_t58_toUpperAscii(const z_t58_t* self);
