static const z_t5814_t _zag1602 = { { .data = "chan_free", .size = 9 }, { .length = 1, .data = _zag1600 }, { .length = 3, .data = _zag1601 }, { .data = "/* the block, once neither end holds it; the lock is not held */\nstatic void z_chan_free(z_chan* b) {\n    free(b->ring);\n    z_cond_destroy(&b->notFull);\n    z_cond_destroy(&b->notEmpty);\n    z_mutex_destroy(&b->m);\n    free(b);\n}", .size = 230 } };
